    // Small anchored popover with a text field: replaces prompt(), which is blocked in the app window.

    function askText(anchor, title, value, onOk, okLabel) {

        document.querySelectorAll(".vfx-ask-pop").forEach(x => x.remove());

        const r = anchor.getBoundingClientRect();

        const pop = document.createElement("div");

        pop.className = "vfx-ask-pop";

        pop.style.cssText = `position: fixed; z-index: 100002; left: ${Math.max(6, Math.min(innerWidth - 270, r.left - 40))}px; top: ${Math.min(innerHeight - 110, r.bottom + 6)}px; width: 260px;

            background: rgba(18,18,22,0.98); border: 1px solid #3f3f46; border-radius: 6px; padding: 8px; font-size: 10.5px; color: #e4e4e7; display: flex; flex-direction: column; gap: 6px; box-shadow: 0 10px 30px rgba(0,0,0,.6);`;

        pop.innerHTML = `<b>${title}</b><input class="ask-in" style="background: #0f0f11; border: 1px solid #3f3f46; color: #fff; padding: 4px 6px; border-radius: 4px; font-size: 11px;">

            <div style="display: flex; gap: 6px;"><button class="vfx-btn ask-ok" style="flex: 1;">${okLabel || "OK"}</button><button class="vfx-btn ask-x">✕</button></div>`;

        document.body.appendChild(pop);

        const inp = pop.querySelector(".ask-in");

        inp.value = value || "";

        ["mousedown", "keydown", "wheel"].forEach(ev => pop.addEventListener(ev, e => e.stopPropagation()));

        const ok = () => { const v = inp.value.trim(); pop.remove(); if (v) onOk(v); };

        pop.querySelector(".ask-ok").onclick = ok;

        pop.querySelector(".ask-x").onclick = () => pop.remove();

        inp.onkeydown = (e) => { e.stopPropagation(); if (e.key === "Enter") ok(); if (e.key === "Escape") pop.remove(); };

        setTimeout(() => { inp.focus(); inp.select(); }, 0);

    }

    window.__vfxAskText = askText;



