        pop.innerHTML = `<b>${uiText("Grow / shrink mask", "Расширить / сузить маску")}</b>

            <div style="display: flex; align-items: center; gap: 6px;"><span style="width: 52px;">${uiText("Width", "Ширина")}</span>

                <input type="range" class="g-px" min="-100" max="100" value="${cur?.px || 0}" style="flex: 1;"><input type="number" class="g-pxn" value="${cur?.px || 0}" style="width: 52px; background: #0f0f11; color: #fff; border: 1px solid #333;"><span>px</span></div>

            <div style="display: flex; align-items: center; gap: 6px;"><span style="width: 52px;">${uiText("Feather", "Мягкость")}</span>

                <input type="range" class="g-f" min="0" max="50" value="${cur?.feather || 0}" style="flex: 1;"><input type="number" class="g-fn" value="${cur?.feather || 0}" style="width: 52px; background: #0f0f11; color: #fff; border: 1px solid #333;"><span>px</span></div>

            <div style="opacity: .55; font-size: 9.5px;">${uiText("+ grows, − shrinks. Always applied to the original mask, so you can change it any time.", "+ расширяет, − сужает. Всегда считается от исходной маски — можно менять сколько угодно.")}</div>

            <div style="display: flex; gap: 6px;"><button class="vfx-btn g-ok" style="flex: 1;">${uiText("Apply", "Применить")}</button>

                <button class="vfx-btn g-reset" ${tipAttr("Back to the original mask", "Вернуть исходную маску")}>${uiText("Reset", "Сброс")}</button><button class="vfx-btn g-x">✕</button></div>`;

