    window.__vfxOpenVideoGenerate = openVideoGeneratePanel;



    let layerSyncTimer1D = null;

    let layerSyncRunning1D = false;

    function scheduleLayerSync1D(delay = 800) {

        clearTimeout(layerSyncTimer1D);

        layerSyncTimer1D = setTimeout(() => { syncDirtyLayers1D().catch(err => console.warn("[Keshiki] Layer sync failed:", err)); }, delay);

    }



    async function syncDirtyLayers1D() {

        if (layerSyncRunning1D) { scheduleLayerSync1D(600); return; }

        const pid = currentProject?.id;

        if (!pid) return;

        layerSyncRunning1D = true;

        try {

            for (const img of mediaImages1D) {

                if (!img || !img._layersDirty || !Array.isArray(img.layers)) continue;

                img._layersDirty = false;

                const sent = img.layers.map(l => ({ id: l.id, src: l.src }));

                const payload = {

                    active_layer_id: img.activeLayerId,

                    layers: img.layers.map(l => ({

                        id: l.id, name: l.name, type: l.type, visible: l.visible !== false,

                        opacity: l.opacity ?? 1, color: l.color || "",

                        skeleton: Array.isArray(l.skeleton) ? l.skeleton : null,

                        transparentBg: !!l.transparentBg,

                        inverted: !!l.inverted,

                        comment: l.comment || "",

                        data: (l.src || "").startsWith("data:image/png") ? l.src : null

                    }))

                };

                const res = await fetch(`/vfx/projects/${encodeURIComponent(pid)}/layers/${encodeURIComponent(img.id)}`, {

                    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload)

                });

                if (!res.ok) { img._layersDirty = true; addLog("ERR", `Layer save failed for ${img.title}: HTTP ${res.status}`); continue; }

                const saved = await res.json();

                (saved.layers || []).forEach(sl => {

                    const local = img.layers.find(l => l.id === sl.id);

                    const sentEntry = sent.find(x => x.id === sl.id);

                    // Swap the data URL for the file URL only if the layer was not edited meanwhile.

                    if (local && sentEntry && local.src === sentEntry.src && sl.src) local.src = sl.src;

                });

            }

            saveProject1DImages();

        } finally {

            layerSyncRunning1D = false;

        }

    }



    let expandedAssetId = null; // top strip: asset shown expanded with its attached files (layers, notes)

    let mediaImages1D = loadProject1DImages(currentProject?.id);

    let activeImageId = mediaImages1D[0]?.id || null;



    // 1D Canvas Zoom/Pan & Paint State

    let img1DZoom = 1.0;

    let img1DPanX = 0;

    let img1DPanY = 0;

    let img1DTool = "pan"; // 'pan' | 'crop' | 'draw' | 'mask' | 'box_mask' | 'eraser'

    let img1DColor = "#ffffff";

    let img1DBrushSize = 8;



    // --- 2D: VIDEOS LIST & STATE ---

    function loadProject2DVideos(projId) {

        if (!projId) return [];

        try {

            const raw = localStorage.getItem(`vfx_proj_${projId}_videos2d`);

            if (raw) {

                const arr = JSON.parse(raw);

                if (Array.isArray(arr)) {

                    return arr.filter(v => v && (v.videoUrl || v.seqPattern) && v.title && (typeof isAssetDeletedLocal !== "function" || !isAssetDeletedLocal(v, projId)));

                }

            }

        } catch (_) {}

        return [];

    }



    function saveProject2DVideos(projId) {

        const id = projId || (currentProject ? currentProject.id : null);

        if (!id) return;

        try {

            localStorage.setItem(`vfx_proj_${id}_videos2d`, JSON.stringify(mediaVideos2D));

        } catch (_) {}

    }



    let mediaVideos2D = loadProject2DVideos(currentProject?.id);



    // Asset folders (project-level, nestable). Items keep `folderId`; null/absent = project root.

    function loadProjectFolders(projId) {

        try { return JSON.parse(localStorage.getItem(`vfx_proj_${projId}_folders`) || "[]") || []; } catch (_) { return []; }

    }

    function saveProjectFolders(projId) {

        const id = projId || (currentProject ? currentProject.id : null);

        if (!id) return;

        try { localStorage.setItem(`vfx_proj_${id}_folders`, JSON.stringify(assetFolders)); } catch (_) {}

    }

    let assetFolders = loadProjectFolders(currentProject?.id);

    let stripFolderId = null;

    let renamingFolderId = null;

    // Video layers per video id (from /vfx/video/<p>/<v>/state), shared by the strip and Details.

    const videoLayersCache = {};

    const videoLayersPending = new Set();

    function fetchVideoLayers(vid, force = false) {

        if (!vid || (!force && (videoLayersCache[vid] || videoLayersPending.has(vid)))) return Promise.resolve(videoLayersCache[vid] || null);

        videoLayersPending.add(vid);

        const pid = encodeURIComponent(currentProject?.id || "sandbox_playground");

        return fetch(`/vfx/video/${pid}/${encodeURIComponent(vid)}/state`).then(r => r.json()).then(st => {

            videoLayersCache[vid] = { layers: st.layers || [], plate: st.plate || null, at: Date.now() };

            return videoLayersCache[vid];

        }).catch(() => null).finally(() => videoLayersPending.delete(vid));

    }

    let stripRerenderTimerG = null;

    window.__vfxStripRerender = () => {

        clearTimeout(stripRerenderTimerG);

        stripRerenderTimerG = setTimeout(() => { if (typeof renderTopViewportBar === "function") renderTopViewportBar(); }, 150);

    };

    window.__vfxInvalidateVideoLayers = (vid) => {

        fetchVideoLayers(vid, true).then(() => {

            if (typeof renderTopViewportBar === "function") renderTopViewportBar();

            if (typeof window.__vfxRefreshDetailsBrowser === "function") window.__vfxRefreshDetailsBrowser();

        });

    };

    function findMediaItemById(id) {

        const lists = [mediaImages1D, mediaVideos2D, typeof mediaScenes3D !== "undefined" ? mediaScenes3D : [],

            typeof mediaAudio !== "undefined" ? mediaAudio : [], typeof mediaTexts !== "undefined" ? mediaTexts : [],

            typeof mediaSplats !== "undefined" ? mediaSplats : []];

        for (const l of lists) { const it = (l || []).find(x => x && x.id === id); if (it) return it; }

        return null;

    }

    function folderPath(fid) {

        const out = []; let f = assetFolders.find(x => x.id === fid); let guard = 0;

        while (f && guard++ < 32) { out.unshift(f); f = assetFolders.find(x => x.id === f.parentId); }

        return out;

    }

    // Context menu: "Move to…" for a file ({itemId}) or a folder ({folderId}).

    function openMoveMenu(e, target) {

        document.querySelectorAll(".vfx-move-menu").forEach(m => m.remove());

        const cur = target.itemId ? (findMediaItemById(target.itemId)?.folderId || null) : (assetFolders.find(f => f.id === target.folderId)?.parentId || null);

        const blocked = new Set();

        if (target.folderId) { // a folder can't go into itself or below itself

            blocked.add(target.folderId);

            let grew = true;

            while (grew) { grew = false; assetFolders.forEach(f => { if (blocked.has(f.parentId) && !blocked.has(f.id)) { blocked.add(f.id); grew = true; } }); }

        }

        const label = (f) => folderPath(f.id).map(x => x.name).join(" / ");

        const opts = [{ id: null, name: uiText("Project (no folder)", "Проект (без папки)") },

            ...assetFolders.filter(f => !blocked.has(f.id)).map(f => ({ id: f.id, name: label(f) })).sort((a, b) => a.name.localeCompare(b.name))];

        const m = document.createElement("div");

        m.className = "vfx-move-menu";

        m.style.cssText = `position: fixed; z-index: 100001; left: ${e.clientX}px; top: ${e.clientY}px; min-width: 200px; max-height: 320px; overflow-y: auto;

            background: rgba(18,18,22,0.98); border: 1px solid #3f3f46; border-radius: 6px; padding: 4px; font-size: 11px; color: #e4e4e7; box-shadow: 0 10px 30px rgba(0,0,0,.6);`;

        m.innerHTML = `<div style="padding: 4px 8px; opacity: .55; font-size: 10px;">${uiText("Move to", "Переместить в")}</div>` + opts.map(o => `

            <div class="mv-opt" data-id="${o.id || ""}" style="display: flex; align-items: center; gap: 6px; padding: 5px 8px; border-radius: 4px; cursor: pointer; ${(o.id || null) === cur ? "opacity: .45; pointer-events: none;" : ""}">

                <i data-lucide="${o.id ? "folder" : "home"}" style="width: 12px; height: 12px; color: #fbbf24;"></i><span>${String(o.name).replace(/</g, "&lt;")}</span></div>`).join("");

        document.body.appendChild(m);

        const r = m.getBoundingClientRect();

        if (r.right > innerWidth) m.style.left = `${innerWidth - r.width - 6}px`;

        if (r.bottom > innerHeight) m.style.top = `${innerHeight - r.height - 6}px`;

        if (typeof lucide !== "undefined" && lucide.createIcons) { try { lucide.createIcons(); } catch (_) {} }

        m.querySelectorAll(".mv-opt").forEach(o => {

            o.onmouseenter = () => o.style.background = "rgba(255,255,255,0.07)";

            o.onmouseleave = () => o.style.background = "transparent";

            o.onclick = () => {

                const fid = o.dataset.id || null;

                if (target.itemId) moveAssetToFolder(target.itemId, fid);

                else { const f = assetFolders.find(x => x.id === target.folderId); if (f) { f.parentId = fid; saveProjectFolders(); } }

                m.remove();

                renderTopViewportBar();

                if (typeof window.__vfxRefreshDetailsBrowser === "function") window.__vfxRefreshDetailsBrowser();

            };

        });

        setTimeout(() => document.addEventListener("mousedown", function h(ev) { if (!m.contains(ev.target)) { m.remove(); document.removeEventListener("mousedown", h, true); } }, true), 0);

    }



    function moveAssetToFolder(itemId, fid) {

        const it = findMediaItemById(itemId);

        if (!it) return false;

        it.folderId = fid || null;

        saveProject1DImages(); saveProject2DVideos();

        try { saveProject3DScenes(); saveProjectAudio(); saveProjectTexts(); } catch (_) {}

        return true;

    }

    let activeVideoId = mediaVideos2D[0]?.id || null;

    let vid2DPlaying = false;

    let vid2DTimer = null;

    let vid2DZoom = 1.0;

    let vid2DPanX = 0;

    let vid2DPanY = 0;

    let vid2DTool = "pan"; // "pan" or "paint_mask"

    let vid2DBrushMode = "add"; // "add" or "subtract"

    let vid2DBrushSize = 25;

    const vid2DUndoStack = [];



    // --- 3D: TRACKS & SCENES LIST ---

    function loadProject3DScenes(projId) {

        if (!projId) return [];

        try {

            const raw = localStorage.getItem(`vfx_proj_${projId}_scenes3d`);

            if (raw) {

                const arr = JSON.parse(raw);

                if (Array.isArray(arr)) return arr.filter(s => (typeof isAssetDeletedLocal !== "function" || !isAssetDeletedLocal(s, projId)) && (typeof is3DMeshDeleted !== "function" || !is3DMeshDeleted(s)));

            }

        } catch (_) {}

        return [];

    }



    function saveProject3DScenes(projId = null) {

        const pid = projId || currentProject?.id;

        if (!pid) return;

        try {

            localStorage.setItem(`vfx_proj_${pid}_scenes3d`, JSON.stringify(mediaScenes3D));

        } catch (_) {}

    }



    let mediaScenes3D = loadProject3DScenes(currentProject?.id);

    // Camera tracks (camera + point cloud) are project media too: one card per tracked video in the strip.

    async function syncTrackScenes() {

        const pid = currentProject?.id || "sandbox_playground";

        let tracks = [];

        try { tracks = (await fetch(`/vfx/track/list?project_id=${encodeURIComponent(pid)}`).then(r => r.json())).tracks || []; } catch (_) { return; }

        let changed = false;

        tracks.forEach(t => {

            const trkId = `trk_${t.video_id}`;

            if (typeof isAssetDeletedLocal === "function" && isAssetDeletedLocal(trkId)) return;

            const vtitle = (mediaVideos2D.find(v => v.id === t.video_id) || {}).title || t.video_id;

            const desc = `${t.frames} ${uiText("frames", "кадров")} · ${t.points} ${uiText("pts", "точек")}${t.focal_mm ? ` · ${Math.round(t.focal_mm)} mm` : ""}`;

            let it = mediaScenes3D.find(s => s.mode === "track" && s.videoId === t.video_id);

            if (!it) {

                mediaScenes3D.push({ id: `trk_${t.video_id}`, title: `${uiText("Track", "Трек")}: ${vtitle}`, badge: "TRACK", desc, mode: "track", videoId: t.video_id, mtime: t.mtime });

                changed = true;

            } else if (it.mtime !== t.mtime || it.desc !== desc) { it.desc = desc; it.mtime = t.mtime; changed = true; }

        });

        if (changed) { saveProject3DScenes(); try { renderTopViewportBar(); } catch (_) {} }

    }

    window.__vfxSyncTrackScenes = syncTrackScenes;



    // --- PERMANENT PROJECT MEDIA ASSETS BLACKLIST & DELETION ---

    function getDeletedAssetsSet(projId = null) {

        const pid = projId || (currentProject ? currentProject.id : "sandbox_playground");

        try {

            const raw = localStorage.getItem(`vfx_deleted_assets_${pid}`);

            const arr = raw ? JSON.parse(raw) : [];

            return new Set(Array.isArray(arr) ? arr : []);

        } catch (_) {

            return new Set();

        }

    }



    function extractFilenameFromAsset(item) {
        if (!item) return "";
        if (typeof item === "string") {
            if (item.includes("filename=")) {
                try {
                    const sp = new URLSearchParams(item.split("?")[1]);
                    const qfn = sp.get("filename");
                    if (qfn) return qfn;
                } catch (_) {}
            }
            const b = item.split("?")[0].split("/").pop();
            return (b && b !== "view") ? b : item;
        }
        if (item.filename && item.filename !== "view") return item.filename;
        const u = item.url || item.videoUrl || item.audioUrl || item.glbUrl || item.ply_url || "";
        if (u && String(u).includes("filename=")) {
            try {
                const sp = new URLSearchParams(String(u).split("?")[1]);
                const qfn = sp.get("filename");
                if (qfn) return qfn;
            } catch (_) {}
        }
        const b = u ? String(u).split("?")[0].split("/").pop() : "";
        return (b && b !== "view") ? b : "";
    }

    function markAssetAsDeletedLocal(item, projId = null) {

        if (!item) return;

        const pid = projId || (currentProject ? currentProject.id : "sandbox_playground");

        const set = getDeletedAssetsSet(pid);

        const extractedFn = extractFilenameFromAsset(item);
        if (extractedFn) set.add(extractedFn);

        if (typeof item === "string") {

            set.add(item);

        } else {

            if (item.id) set.add(String(item.id));

            if (item.filename && item.filename !== "view") set.add(String(item.filename));

            const u = item.url || item.videoUrl || item.audioUrl || item.glbUrl || item.ply_url || "";

            if (u) {

                set.add(String(u));

                const base = String(u).split("?")[0].split("/").pop();

                if (base && base !== "view") set.add(base);

            }

        }

        try {

            localStorage.setItem(`vfx_deleted_assets_${pid}`, JSON.stringify(Array.from(set)));

        } catch (_) {}

    }

    window.__vfxMarkAssetAsDeletedLocal = markAssetAsDeletedLocal;



    function isAssetDeletedLocal(item, projId = null) {

        if (!item) return false;

        const pid = projId || (currentProject ? currentProject.id : "sandbox_playground");

        const set = getDeletedAssetsSet(pid);

        if (set.size === 0) return false;

        const extractedFn = extractFilenameFromAsset(item);
        if (extractedFn && set.has(extractedFn)) return true;

        if (typeof item === "string") {
            if (set.has(item)) return true;
            const b = item.split("?")[0].split("/").pop();
            return !!(b && b !== "view" && set.has(b));
        }

        const u = item.url || item.videoUrl || item.audioUrl || item.glbUrl || item.ply_url || "";

        const base = u ? String(u).split("?")[0].split("/").pop() : "";

        return (item.id && set.has(String(item.id)))

            || (item.filename && item.filename !== "view" && set.has(String(item.filename)))

            || (u && set.has(String(u)))

            || (base && base !== "view" && set.has(base));

    }

    window.__vfxIsAssetDeletedLocal = isAssetDeletedLocal;



    async function deleteProjectMediaAsset(type, item) {

        if (!item) return;

        const pid = currentProject?.id || "sandbox_playground";

        markAssetAsDeletedLocal(item, pid);



        const u = item.url || item.videoUrl || item.audioUrl || item.glbUrl || item.ply_url || "";

        let fn = extractFilenameFromAsset(item);
        let sub = item.sub || "";
        if (!sub && u && String(u).includes("subfolder=")) {
            try {
                const sp = new URLSearchParams(String(u).split("?")[1]);
                sub = sp.get("subfolder") || "";
            } catch (_) {}
        }



        // 1. Tell backend to delete physical file from disk & remove from project.json

        try {

            await fetch(`/vfx/projects/${encodeURIComponent(pid)}/delete_asset`, {

                method: "POST",

                headers: { "Content-Type": "application/json" },

                body: JSON.stringify({

                    id: item.id || "",

                    url: u,

                    filename: fn,

                    sub: sub

                })

            });

        } catch (e) {

            console.warn("delete_asset request error:", e);

        }



        // 2. Filter from active in-memory arrays and update currentProject state

        if (type === "image" || type === "1d-image" || type === "photo") {

            mediaImages1D = mediaImages1D.filter(i => i.id !== item.id && (!u || i.url !== u) && (!fn || i.filename !== fn));

            if (activeImageId === item.id) activeImageId = mediaImages1D[0]?.id || null;

            if (currentProject) currentProject.mediaImages1D = mediaImages1D;

            saveProject1DImages(pid);

        } else if (type === "video" || type === "2d-video") {

            mediaVideos2D = mediaVideos2D.filter(v => v.id !== item.id && (!u || v.videoUrl !== u) && (!fn || v.filename !== fn));

            if (activeVideoId === item.id) activeVideoId = mediaVideos2D[0]?.id || null;

            if (currentProject) currentProject.mediaVideos2D = mediaVideos2D;

            saveProject2DVideos(pid);

        } else if (type === "audio") {

            mediaAudio = mediaAudio.filter(a => a.id !== item.id && (!u || (a.audioUrl !== u && a.url !== u)));

            if (activeAudioId === item.id) activeAudioId = mediaAudio[0]?.id || null;

            if (currentProject) currentProject.mediaAudio = mediaAudio;

            saveProjectAudio(pid);

        } else if (type === "3d" || type === "3d-scene" || type === "mesh") {

            if (typeof delete3DMeshAsset === "function" && (item.mode === "mesh" || Boolean(item.filename || item.url || item.glbUrl))) {

                try { await delete3DMeshAsset(item); } catch (_) {}

            }

            mediaScenes3D = mediaScenes3D.filter(s => s.id !== item.id && (!u || (s.url !== u && s.glbUrl !== u)));

            if (activeScene3DId === item.id) activeScene3DId = mediaScenes3D[0]?.id || null;

            if (currentProject) currentProject.mediaScenes3D = mediaScenes3D;

            saveProject3DScenes(pid);

        } else if (type === "splat") {

            mediaSplats = mediaSplats.filter(s => s.id !== item.id && (!u || s.ply_url !== u));

            if (activeSplatId === item.id) activeSplatId = mediaSplats[0]?.id || null;

            if (currentProject) currentProject.mediaSplats = mediaSplats;

            saveProjectSplats(pid);

        } else if (type === "text") {

            mediaTexts = mediaTexts.filter(t => t.id !== item.id);

            if (activeTextId === item.id) activeTextId = mediaTexts[0]?.id || null;

            if (currentProject) currentProject.mediaTexts = mediaTexts;

            saveProjectTexts(pid);

        }



        // 3. Persist project state to disk and await completion

        try {

            await saveCurrentProject();

        } catch (e) {

            console.warn("saveCurrentProject after delete failed:", e);

        }



        addLog("UI", `Permanently deleted ${type} asset: ${item.title || item.id}`);

        try { renderTopViewportBar(); } catch (_) {}

        try { renderMainViewport(); } catch (_) {}

        if (typeof renderDetailsInstances === "function") {

            try { renderDetailsInstances(); } catch (_) {}

        }

    }

    window.__vfxDeleteProjectMediaAsset = deleteProjectMediaAsset;



    const DELETED_MESHES_STORAGE_KEY = "vfx_deleted_meshes_v1";

    function getDeletedMeshesSet() {

        try {

            const raw = localStorage.getItem(DELETED_MESHES_STORAGE_KEY);

            const arr = raw ? JSON.parse(raw) : [];

            return new Set(Array.isArray(arr) ? arr : []);

        } catch (_) {

            return new Set();

        }

    }

    function markMeshAsDeletedLocal(item) {

        if (!item) return;

        const set = getDeletedMeshesSet();

        if (item.id) set.add(String(item.id));

        if (item.filename) {

            set.add(String(item.filename));

            set.add(`mesh_${item.filename}`);

        }

        const u = item.url || item.glbUrl || "";

        if (u) {

            set.add(String(u));

            const base = String(u).split("?")[0].split("/").pop();

            if (base) {

                set.add(base);

                set.add(`mesh_${base}`);

            }

        }

        try {

            localStorage.setItem(DELETED_MESHES_STORAGE_KEY, JSON.stringify(Array.from(set)));

        } catch (_) {}

    }

    function is3DMeshDeleted(item) {

        if (!item) return false;

        const set = getDeletedMeshesSet();

        if (set.size === 0) return false;

        const u = item.url || item.glbUrl || "";

        const base = u ? String(u).split("?")[0].split("/").pop() : "";

        return (item.id && set.has(String(item.id)))

            || (item.filename && set.has(String(item.filename)))

            || (u && set.has(String(u)))

            || (base && set.has(base));

    }

    async function delete3DMeshAsset(item) {

        if (!item) return;

        markMeshAsDeletedLocal(item);

        markAssetAsDeletedLocal(item);

        const u = item.url || item.glbUrl || (item.filename ? `/vfx/mesh3d/file/${item.filename}` : "");

        const base = item.filename || (u ? String(u).split("?")[0].split("/").pop() : "");

        try {

            await fetch("/vfx/mesh3d/delete", {

                method: "POST",

                headers: { "Content-Type": "application/json" },

                body: JSON.stringify({

                    id: item.id || "",

                    filename: base || "",

                    url: u || ""

                })

            });

        } catch (_) {}

        mediaScenes3D = mediaScenes3D.filter(s => {

            if (s.id === item.id) return false;

            if (base && (s.filename === base || s.id === `mesh_${base}`)) return false;

            if (u && (s.url === u || s.glbUrl === u)) return false;

            return !is3DMeshDeleted(s);

        });

        if (activeScene3DId && !mediaScenes3D.some(s => s.id === activeScene3DId)) {

            activeScene3DId = mediaScenes3D[0]?.id || null;

        }

        if (Array.isArray(meshLibrary)) {

            meshLibrary = meshLibrary.filter(m => !is3DMeshDeleted(m) && m.id !== item.id && (!base || m.filename !== base));

        }

        if (window.__lastGeneratedGLB && (window.__lastGeneratedGLB === u || (base && window.__lastGeneratedGLB.endsWith(base)))) {

            const nextMesh = Array.isArray(meshLibrary) && meshLibrary.length > 0 ? meshLibrary[0] : null;

            window.__lastGeneratedGLB = nextMesh ? nextMesh.url : "";

            window.__lastGeneratedTextures = nextMesh ? (nextMesh.textures || {}) : {};

            if (typeof window.__updateMeshGenCanvasLayers === "function") {

                try { window.__updateMeshGenCanvasLayers(); } catch (_) {}

            }

        }

        saveProject3DScenes();

        if (typeof saveCurrentProject === "function") saveCurrentProject();

        try { renderTopViewportBar(); } catch (_) {}

        if (typeof renderDetailsInstances === "function") {

            try { renderDetailsInstances(); } catch (_) {}

        }

    }

    window.__vfxDelete3DMeshAsset = delete3DMeshAsset;



    // Generated 3D meshes (.GLB) are synced into the 3D gallery strip alongside camera tracks

    async function syncGeneratedMeshesToScenes3D() {

        let meshes = [];

        try {

            const res = await fetch("/vfx/mesh3d/list").then(r => r.json());

            meshes = (res.meshes || []).filter(m => !is3DMeshDeleted(m));

        } catch (_) { return; }

        let changed = false;

        const beforeLen = mediaScenes3D.length;

        mediaScenes3D = mediaScenes3D.filter(s => !(s.mode === "mesh" && (is3DMeshDeleted(s) || /^mesh_job3d_/i.test(String(s.filename || (s.url || "").split("/").pop() || "")))));

        if (mediaScenes3D.length !== beforeLen) changed = true;



        meshes.forEach(m => {

            let it = mediaScenes3D.find(s => s.id === m.id || s.filename === m.filename);

            const desc = `${(m.engine || "3D").toUpperCase()} • ${m.size_mb != null ? m.size_mb + ' MB' : ''}`;

            if (!it) {

                mediaScenes3D.push({

                    id: m.id || `mesh_${m.filename}`,

                    title: m.title || m.filename,

                    badge: "3D MESH",

                    desc: desc,

                    mode: "mesh",

                    filename: m.filename,

                    url: m.url,

                    engine: m.engine,

                    textures: m.textures || {},

                    mtime: m.created_at || Date.now()

                });

                changed = true;

            } else {

                if (m.textures && Object.keys(m.textures).length > 0) {

                    it.textures = Object.assign(it.textures || {}, m.textures);

                }

            }

        });

        if (changed) {

            saveProject3DScenes();

            try { renderTopViewportBar(); } catch (_) {}

        }

    }

    window.__vfxSyncGeneratedMeshesToScenes3D = syncGeneratedMeshesToScenes3D;



    // --- UNREAL-STYLE 3D LEVEL MAPS & CONTAINERS ---

    function syncActiveLevelData() {

        if (!activeScene3DId && !mediaScenes3D.length) return;

        const curLevel = mediaScenes3D.find(s => s.id === activeScene3DId && (s.mode === "level" || s.mode === "custom"))
            || mediaScenes3D.find(s => s.mode === "level" || s.mode === "custom")
            || mediaScenes3D[0];

        if (curLevel && typeof onExportManifest === "function") {

            const liveManifest = onExportManifest();

            curLevel.manifest = JSON.parse(JSON.stringify(liveManifest || []));

            const objCount = curLevel.manifest.length;

            const meshCount = curLevel.manifest.filter(o => o.type === "mesh" || o.glbUrl).length;

            const camCount = curLevel.manifest.filter(o => o.type === "camera").length;

            curLevel.desc = `${objCount} ${uiText("actors", "объектов")}${meshCount ? ` · ${meshCount} mesh` : ""}${camCount ? ` · ${camCount} cam` : ""}`;

            curLevel.mtime = Date.now();

            saveProject3DScenes();

        }

    }

    window.__vfxSyncActiveLevelData = syncActiveLevelData;



    function ensureDefaultLevelExists() {

        const hasLevel = mediaScenes3D.some(s => s.mode === "level" || s.mode === "custom");

        if (!hasLevel) {

            const curManifest = (typeof onExportManifest === "function") ? onExportManifest() : [];

            const objCount = (curManifest || []).length;

            const initLevel = {

                id: `lvl_default_${Date.now()}`,

                title: uiText("Level 1: Main Stage", "Уровень 1: Главная сцена"),

                badge: "LEVEL",

                desc: `${objCount} ${uiText("actors (Active Level)", "объектов (Активный уровень)")}`,

                mode: "level",

                manifest: curManifest || [],

                mtime: Date.now()

            };

            mediaScenes3D.unshift(initLevel);

            activeScene3DId = initLevel.id;

            saveProject3DScenes();

        }

    }

    window.__vfxEnsureDefaultLevelExists = ensureDefaultLevelExists;



    function createNewLevel(customName = null) {

        syncActiveLevelData();

        const levelCount = mediaScenes3D.filter(s => s.mode === "level" || s.mode === "custom").length;

        const levelTitle = customName || `${uiText("Level", "Уровень")} ${levelCount + 1}: ${uiText("New Stage", "Новая сцена")}`;



        const newLvl = {

            id: `lvl_${Date.now()}`,

            title: levelTitle,

            badge: "LEVEL",

            desc: `0 ${uiText("actors (Empty Level)", "объектов (Пустой уровень)")}`,

            mode: "level",

            manifest: [], // Empty container!

            mtime: Date.now()

        };



        mediaScenes3D.unshift(newLvl);

        activeScene3DId = newLvl.id;

        saveProject3DScenes();



        if (typeof onLoadManifest === "function") {

            onLoadManifest([]);

        }



        if (mainViewDim !== "3D") {

            switchMainDimension("3D");

        }



        if (typeof renderDetailsInstances === "function") {

            renderDetailsInstances();

        }



        renderTopViewportBar();

        showToastNotification(uiText(`Created empty Level «${levelTitle}». Build your scene here!`, `Создан пустой уровень «${levelTitle}». Начинайте строить сцену!`));

        addLog("3D", `Created new 3D Level container: ${levelTitle}`);

        return newLvl;

    }

    window.__vfxCreateNewLevel = createNewLevel;



    function switchActiveLevel(levelItem) {

        if (!levelItem) return;

        if (activeScene3DId === levelItem.id && mainViewDim === "3D") return;



        syncActiveLevelData();

        activeScene3DId = levelItem.id;

        addLog("3D", `Switch Level → ${levelItem.title}`);



        if (typeof onLoadManifest === "function") {

            onLoadManifest(levelItem.manifest || []);

        }



        if (mainViewDim !== "3D") {

            switchMainDimension("3D");

        }



        if (typeof renderDetailsInstances === "function") {

            renderDetailsInstances();

        }



        renderTopViewportBar();

        showToastNotification(uiText(`Loaded Level «${levelItem.title}» (${(levelItem.manifest || []).length} actors)`, `Загружен уровень «${levelItem.title}» (${(levelItem.manifest || []).length} объектов)`));

    }

    window.__vfxSwitchActiveLevel = switchActiveLevel;



    function saveLevelSnapshot() {

        syncActiveLevelData();

        const curLevel = mediaScenes3D.find(s => s.id === activeScene3DId && (s.mode === "level" || s.mode === "custom"));

        const baseName = curLevel ? curLevel.title : uiText("Level", "Уровень");

        const snapCount = mediaScenes3D.filter(s => s.title.includes(baseName)).length;

        const snapTitle = `${baseName} (Copy ${snapCount})`;

        const liveManifest = (typeof onExportManifest === "function") ? onExportManifest() : [];



        const snapLvl = {

            id: `lvl_snap_${Date.now()}`,

            title: snapTitle,

            badge: "SNAPSHOT",

            desc: `${(liveManifest || []).length} ${uiText("actors (Snapshot)", "объектов (Слепок)")}`,

            mode: "level",

            manifest: JSON.parse(JSON.stringify(liveManifest || [])),

            mtime: Date.now()

        };



        mediaScenes3D.unshift(snapLvl);

        activeScene3DId = snapLvl.id;

        saveProject3DScenes();

        renderTopViewportBar();

        showToastNotification(uiText(`Saved snapshot «${snapTitle}» into 3D Gallery`, `Сохранен слепок «${snapTitle}» в галерею 3D`));

        addLog("3D", `Saved Level Snapshot: ${snapTitle}`);

        return snapLvl;

    }

    window.__vfxSaveLevelSnapshot = saveLevelSnapshot;



    async function activateTrackScene(scn) {

        const pid = currentProject?.id || "sandbox_playground";

        // Save current scene before activating track so sun & props are preserved
        syncActiveLevelData();
        if (typeof onSaveScene3D === "function") {
            try { await onSaveScene3D(); } catch (_) {}
        }

        const r = await fetch("/vfx/track/activate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ project_id: pid, video_id: scn.videoId }) }).then(x => x.json()).catch(e => ({ error: e.message }));

        if (r.error) { showToastNotification(`${uiText("Track", "Трек")}: ${r.error}`, true); return; }

        try { localStorage.removeItem("vfx_3d_lidar_deleted"); localStorage.removeItem("vfx_3d_shot_cam_deleted"); } catch (_) {}

        if (typeof onReloadSceneData === "function") await onReloadSceneData(currentProject, { keepExistingActors: true });

        showToastNotification(uiText(`Track «${scn.title}» is in the scene: camera + point cloud`, `«${scn.title}» в сцене: камера + облако точек`));

    }

    // --- 3D BAKED LAYOUT GALLERY SYNC ---

    async function syncBakedLayoutToGallery(forceBakeTime = null) {

        try {

            const res = await fetch("/vfx/layout_render_info").then(r => r.json());

            if (!res || !res.has_renders || !res.count) return;

            const bakeTime = forceBakeTime || Date.now();

            const totalF = res.count;

            const fps = (typeof projectFPS === "number" && projectFPS > 0) ? projectFPS : 24;

            if (forceBakeTime) {
                try {
                    const pid = (currentProject && currentProject.id) || "sandbox_playground";
                    const delSet = typeof getDeletedAssetsSet === "function" ? getDeletedAssetsSet(pid) : null;
                    if (delSet) {
                        ["baked_layout_sequence", "baked_layout_snap", "layout_render.mp4", "/vfx/layout_render.mp4", "/vfx/layout_render/0", "0"].forEach(k => {
                            delSet.delete(k);
                            for (const item of Array.from(delSet)) {
                                if (String(item).includes("layout_render")) delSet.delete(item);
                            }
                        });
                        localStorage.setItem(`vfx_deleted_assets_${pid}`, JSON.stringify(Array.from(delSet)));
                    }
                } catch (_) {}
            }

            let changed = false;

            let existingVid = mediaVideos2D.find(v => v.id === "baked_layout_sequence" || v.badge === "BAKED");

            if (!existingVid) {

                if (!forceBakeTime && typeof isAssetDeletedLocal === "function" && isAssetDeletedLocal("baked_layout_sequence")) {
                    // keep skipped on passive sync if user deleted it
                } else {
                    existingVid = {

                        id: "baked_layout_sequence",

                        title: "Baked 3D Layout (" + totalF + "f)",

                        badge: "BAKED",

                        type: "seq",

                        seqPattern: "/vfx/layout_render/{f}?t=" + bakeTime,

                        posterUrl: "/vfx/layout_render/0?t=" + bakeTime,

                        videoUrl: "/vfx/layout_render.mp4?t=" + bakeTime,

                        url: "/vfx/layout_render.mp4?t=" + bakeTime,

                        totalFrames: totalF,

                        fps: fps,

                        duration: (totalF / fps).toFixed(1) + "s",

                        comment: uiText("Baked from 3D Viewport Shot Camera", "Запечённая сиквенция 3D камеры"),

                        comments: [],

                        maskTracks: []

                    };

                    mediaVideos2D.unshift(existingVid);

                    changed = true;
                }

            } else {

                existingVid.title = "Baked 3D Layout (" + totalF + "f)";

                existingVid.type = "seq";

                existingVid.badge = "BAKED";

                existingVid.seqPattern = "/vfx/layout_render/{f}?t=" + bakeTime;

                existingVid.posterUrl = "/vfx/layout_render/0?t=" + bakeTime;

                existingVid.videoUrl = "/vfx/layout_render.mp4?t=" + bakeTime;

                existingVid.url = "/vfx/layout_render.mp4?t=" + bakeTime;

                existingVid.totalFrames = totalF;

                existingVid.fps = fps;

                existingVid.duration = (totalF / fps).toFixed(1) + "s";

                const idx = mediaVideos2D.indexOf(existingVid);

                if (idx > 0) {

                    mediaVideos2D.splice(idx, 1);

                    mediaVideos2D.unshift(existingVid);

                }

                changed = true;

            }



            let existingImg = mediaImages1D.find(i => i.id === "baked_layout_snap");

            if (!existingImg) {

                if (!forceBakeTime && typeof isAssetDeletedLocal === "function" && isAssetDeletedLocal("baked_layout_snap")) {
                    // keep skipped on passive sync if user deleted it
                } else {
                    existingImg = {

                        id: "baked_layout_snap",

                        title: uiText("Baked Layout Still", "Запечённый 3D кадр"),

                        badge: "BAKE",

                        url: "/vfx/layout_render/0?t=" + bakeTime,

                        comment: uiText("Baked 3D layout snapshot (" + totalF + " frames)", "Снимок запечённого 3D лейаута (" + totalF + " кадров)")

                    };

                    mediaImages1D.unshift(existingImg);

                    changed = true;
                }

            } else {

                existingImg.url = "/vfx/layout_render/0?t=" + bakeTime;

                existingImg.comment = uiText("Baked 3D layout snapshot (" + totalF + " frames)", "Снимок запечённого 3D лейаута (" + totalF + " кадров)");

                const idx = mediaImages1D.indexOf(existingImg);

                if (idx > 0) {

                    mediaImages1D.splice(idx, 1);

                    mediaImages1D.unshift(existingImg);

                }

                changed = true;

            }



            if (changed) {

                saveProject2DVideos();

                saveProject1DImages();

                try { renderTopViewportBar(); } catch (_) {}

            }

            return existingVid;

        } catch (e) {

            console.warn("syncBakedLayoutToGallery error:", e);

        }

    }

    window.__vfxSyncBakedLayoutToGallery = syncBakedLayoutToGallery;

    window.__vfxAddBakedLayoutToGallery = ({ totalFrames, fps, bakeTime }) => {

        return syncBakedLayoutToGallery(bakeTime).then((vid) => {

            showToastNotification(uiText("🎬 Camera Render (" + totalFrames + "f) added to Gallery", "🎬 Рендер камеры (" + totalFrames + " к.) добавлен в галерею"));
            return vid;

        });

    };



    // --- SYNC GENERATED VIDEOS FROM COMFYUI TO 2D GALLERY ---
    async function syncGeneratedVideosToGallery() {
        try {
            const pid = (currentProject && currentProject.id) || "sandbox_playground";
            let changed = false;

            // 1. Clean up misclassified .mp4 files from mediaImages1D
            if (Array.isArray(mediaImages1D)) {
                const beforeLen = mediaImages1D.length;
                mediaImages1D = mediaImages1D.filter(i => {
                    const u = String(i?.url || "").toLowerCase();
                    return !u.endsWith(".mp4") && !u.endsWith(".mov") && !u.endsWith(".webm") && !u.includes(".mp4&");
                });
                if (mediaImages1D.length !== beforeLen) {
                    changed = true;
                    saveProject1DImages(pid);
                }
            }

            // 2. Query ComfyUI /history to discover any completed output videos
            const hResp = await fetch("/history").catch(() => null);
            if (hResp && hResp.ok) {
                const historyData = await hResp.json().catch(() => ({}));
                for (const promptId of Object.keys(historyData)) {
                    const item = historyData[promptId] || {};
                    const outputs = item.outputs || {};
                    for (const nid of Object.keys(outputs)) {
                        const nout = outputs[nid] || {};
                        const allAssets = [...(nout.images || []), ...(nout.videos || []), ...(nout.gifs || [])];
                        for (const a of allAssets) {
                            const fn = a?.filename || "";
                            const itype = a?.type || "output";
                            const sub = a?.subfolder || "";
                            const isVid = fn.toLowerCase().endsWith(".mp4") || fn.toLowerCase().endsWith(".mov") || fn.toLowerCase().endsWith(".webm") || (a?.metadata && a.metadata.kind === "video");
                            
                            if (isVid && itype === "output" && (sub.includes("keshiki") || fn.includes("video_"))) {
                                const url = `/view?filename=${encodeURIComponent(fn)}&type=${encodeURIComponent(itype)}` + (sub ? `&subfolder=${encodeURIComponent(sub)}` : "");
                                const genId = "vid_gen_" + fn.replace(/[^a-zA-Z0-9_-]/g, "_");
                                
                                if (typeof isAssetDeletedLocal === "function") {
                                    if (isAssetDeletedLocal(fn, pid) || isAssetDeletedLocal(url, pid) || isAssetDeletedLocal(genId, pid)) continue;
                                }

                                const exists = mediaVideos2D.some(v => 
                                    (v.videoUrl && (v.videoUrl === url || v.videoUrl.includes(fn))) ||
                                    (v.url && (v.url === url || v.url.includes(fn))) ||
                                    v.id === genId
                                );

                                if (!exists) {
                                    let cleanTitle = `LTX Video: ${fn.replace(".mp4", "")}`;
                                    const m = fn.match(/video_(shot_\d+)/);
                                    if (m) cleanTitle = `LTX Video: ${m[1]}`;
                                    
                                    const newVid = {
                                        id: genId,
                                        title: cleanTitle,
                                        badge: "LTX-2.5",
                                        type: "html5",
                                        videoUrl: url,
                                        url: url,
                                        filename: fn,
                                        sub: sub,
                                        fps: (a?.metadata && a.metadata.fps) || (typeof getProjectFPS === "function" ? getProjectFPS() : 24) || 24,
                                        comment: `Generated by LTX-2.5 in ComfyUI (${fn})`
                                    };
                                    mediaVideos2D.unshift(newVid);
                                    changed = true;
                                }
                            }
                        }
                    }
                }
            }

            if (changed) {
                saveProject2DVideos(pid);
                if (currentProject) {
                    currentProject.mediaVideos2D = mediaVideos2D;
                    currentProject.mediaImages1D = mediaImages1D;
                }
                if (!activeVideoId && mediaVideos2D.length > 0) {
                    activeVideoId = mediaVideos2D[0].id;
                }
                renderTopViewportBar();
                renderMainViewport();
            }
        } catch (err) {
            console.warn("[syncGeneratedVideosToGallery]", err);
        }
    }
    window.__vfxSyncGeneratedVideosToGallery = syncGeneratedVideosToGallery;

    // --- SYNC GENERATED IMAGES FROM COMFYUI TO 1D GALLERY ---
    async function syncGeneratedImagesToGallery() {
        try {
            const pid = (currentProject && currentProject.id) || "sandbox_playground";
            let changed = false;

            const hResp = await fetch("/history").catch(() => null);
            if (hResp && hResp.ok) {
                const historyData = await hResp.json().catch(() => ({}));
                for (const promptId of Object.keys(historyData)) {
                    const item = historyData[promptId] || {};
                    const outputs = item.outputs || {};
                    for (const nid of Object.keys(outputs)) {
                        const nout = outputs[nid] || {};
                        const allAssets = [...(nout.images || [])];
                        for (const a of allAssets) {
                            const fn = a?.filename || "";
                            const itype = a?.type || "output";
                            const sub = a?.subfolder || "";
                            const lowerFn = fn.toLowerCase();
                            const isImg = lowerFn.endsWith(".png") || lowerFn.endsWith(".jpg") || lowerFn.endsWith(".jpeg") || lowerFn.endsWith(".webp");
                            
                            if (isImg && itype === "output" && (sub.includes("keshiki") || lowerFn.includes("keshiki") || lowerFn.includes("shot_") || lowerFn.includes("flux"))) {
                                const url = `/view?filename=${encodeURIComponent(fn)}&type=${encodeURIComponent(itype)}` + (sub ? `&subfolder=${encodeURIComponent(sub)}` : "");
                                const genId = "img_gen_" + fn.replace(/[^a-zA-Z0-9_-]/g, "_");
                                
                                if (typeof isAssetDeletedLocal === "function") {
                                    if (isAssetDeletedLocal(fn, pid) || isAssetDeletedLocal(url, pid) || isAssetDeletedLocal(genId, pid)) continue;
                                }

                                const exists = mediaImages1D.some(i => 
                                    (i.url && (i.url === url || i.url.includes(fn))) ||
                                    i.id === genId
                                );

                                if (!exists) {
                                    let cleanTitle = `FLUX: ${fn.replace(/\.[a-zA-Z0-9]+$/, "")}`;
                                    const m = fn.match(/shot_(\d+)/i);
                                    if (m) cleanTitle = `FLUX: Shot ${m[1]}`;
                                    
                                    const newImg = {
                                        id: genId,
                                        title: cleanTitle,
                                        badge: "FLUX.3",
                                        url: url,
                                        filename: fn,
                                        sub: sub,
                                        fallbackUrl: null,
                                        comment: `Generated by ComfyUI (${fn})`,
                                        layerDataUrl: null,
                                        layerVisible: true
                                    };
                                    mediaImages1D.unshift(newImg);
                                    changed = true;
                                }
                            }
                        }
                    }
                }
            }

            if (changed) {
                saveProject1DImages(pid);
                if (currentProject) {
                    currentProject.mediaImages1D = mediaImages1D;
                }
                if (!activeImageId && mediaImages1D.length > 0) {
                    activeImageId = mediaImages1D[0].id;
                }
                renderTopViewportBar();
                renderMainViewport();
            }
        } catch (err) {
            console.warn("[syncGeneratedImagesToGallery]", err);
        }
    }
    window.__vfxSyncGeneratedImagesToGallery = syncGeneratedImagesToGallery;

    setTimeout(() => { try { syncTrackScenes(); syncGeneratedMeshesToScenes3D(); syncBakedLayoutToGallery(); syncGeneratedVideosToGallery(); syncGeneratedImagesToGallery(); ensureDefaultLevelExists(); } catch (_) {} }, 1500);

