    // --- AUDIO: VOICE & MUSIC TRACKS ---

    function loadProjectAudio(projId) {

        if (!projId) return [];

        try {

            const raw = localStorage.getItem(`vfx_proj_${projId}_audio`);

            if (raw) {

                const arr = JSON.parse(raw);

                if (Array.isArray(arr)) return arr.filter(a => a && (a.url || a.audioUrl) && a.title && (typeof isAssetDeletedLocal !== "function" || !isAssetDeletedLocal(a, projId)));

            }

        } catch (_) {}

        return [];

    }



