    function loadSavedAgentConfig() {
        const def = {
            provider: "ollama",
            model_name: "",
            api_key: "",
            api_url: "http://127.0.0.1:11434",
            context_tokens: 80000
        };
        try {
            const raw = localStorage.getItem("vfx_agent_config");
            if (raw) {
                const cfg = { ...def, ...JSON.parse(raw) };
                if (!cfg.context_tokens || cfg.context_tokens < 80000) {
                    cfg.context_tokens = 80000;
                }

                // Legacy providers (removed): fall back to local Ollama

                if (["antigravity", "gemma4_ltx", "gemma4_12b"].includes(cfg.provider)) {

                    cfg.provider = "ollama";

                    if (/gemma4-12b|\.safetensors$/i.test(cfg.model_name || "")) cfg.model_name = "";

                    if (/\/v1\/?$/.test(cfg.api_url || "")) cfg.api_url = cfg.api_url.replace(/\/v1\/?$/, "");

                }

                return cfg;

            }

        } catch (_) {}

        return def;

    }

    function saveAgentConfig() {

        try {

            localStorage.setItem("vfx_agent_config", JSON.stringify(agentConfig));

        } catch (_) {}

        try {

            const dockSel = document.getElementById("dock-agent-quick-model-select");

            if (dockSel && agentConfig.model_name && dockSel.value !== agentConfig.model_name) {

                dockSel.value = agentConfig.model_name;

            }

            const tabSel = document.getElementById("agent-tab-quick-model-select");

            if (tabSel && agentConfig.model_name && tabSel.value !== agentConfig.model_name) {

                tabSel.value = agentConfig.model_name;

            }

            const dockLbl = document.getElementById("dock-provider-label");

            if (dockLbl && agentConfig.provider) {

                dockLbl.innerText = agentConfig.provider.toUpperCase();

            }

            const tabBadge = document.getElementById("agent-tab-provider-badge");

            if (tabBadge && agentConfig.provider) {

                tabBadge.innerText = agentConfig.provider.toUpperCase();

            }

        } catch (_) {}

    }

    let agentConfig = loadSavedAgentConfig();



    function loadProjectChatHistory(projId) {

        const pid = projId || (currentProject ? currentProject.id : "sandbox_playground");

        try {

            const raw = localStorage.getItem(`vfx_proj_${pid}_chat_history`);

            if (raw) {

                const arr = JSON.parse(raw);

                if (Array.isArray(arr)) {

                    arr.forEach(item => {

                        if (item && item.generation && item.generation.status === "running") {

                            item.generation.status = "interrupted";

                        }

                    });

                    return arr;

                }

            }

        } catch (_) {}

        return [];

    }



    function sanitizeChatMsgForStorage(m) {
        if (!m || typeof m !== "object") return m;
        const copy = { ...m };
        if (typeof copy.image === "string" && copy.image.startsWith("data:") && copy.image.length > 150000) copy.image = "";
        if (typeof copy.mediaUrl === "string" && copy.mediaUrl.startsWith("data:") && copy.mediaUrl.length > 150000) copy.mediaUrl = "";
        if (Array.isArray(copy.images)) {
            copy.images = copy.images.filter(u => !(typeof u === "string" && u.startsWith("data:") && u.length > 150000));
        }
        if (Array.isArray(copy.refs)) {
            copy.refs = copy.refs.map(r => {
                if (!r || typeof r !== "object") return r;
                const rc = { ...r };
                for (const k of Object.keys(rc)) {
                    if (typeof rc[k] === "string" && rc[k].startsWith("data:") && rc[k].length > 150000) {
                        rc[k] = "";
                    }
                }
                return rc;
            });
        }
        return copy;
    }

    function saveProjectChatHistory(projId) {

        const pid = projId || (currentProject ? currentProject.id : "sandbox_playground");

        try {

            const trimmed = chatHistory.slice(-200).map(sanitizeChatMsgForStorage);

            localStorage.setItem(`vfx_proj_${pid}_chat_history`, JSON.stringify(trimmed));

            fetch("/vfx/agent/history", {

                method: "POST",

                headers: { "Content-Type": "application/json" },

                body: JSON.stringify({ project_id: pid, history: trimmed })

            }).catch(() => {});

        } catch (_) {}

    }



