    async function applyProcessEnabledStateToStrip() {

        if (!pipelineProcessesState) await fetchPipelineProcessesState();

        const procs = pipelineProcessesState?.processes || [];

        const disabled = new Set(procs.filter(p => p.config?.enabled === false).map(p => p.id));

        document.querySelectorAll("button[data-tab-id]").forEach(btn => {

            const tid = btn.dataset.tabId;

            if (!PROCESS_TAB_IDS.includes(tid)) return;

            const off = disabled.has(tid);

            btn.classList.toggle("vfx-tab-disabled", off);

            btn.style.opacity = off ? "0.3" : "";

            btn.style.filter = off ? "grayscale(1)" : "";

        });

    }

