    // Global helper for copying text to clipboard with animated button feedback and toast

    function copyTextWithFeedback(textToCopy, btnEl, successMsg) {

        if (!textToCopy) return;

        const origHtml = btnEl ? btnEl.innerHTML : "";

        const fallbackCopy = (str) => {

            try {

                const ta = document.createElement("textarea");

                ta.value = str;

                ta.style.position = "fixed";

                ta.style.left = "-9999px";

                ta.style.top = "-9999px";

                document.body.appendChild(ta);

                ta.focus();

                ta.select();

                const ok = document.execCommand("copy");

                document.body.removeChild(ta);

                return ok;

            } catch (e) {

                return false;

            }

        };



        const notifyDone = () => {

            if (btnEl) {

                btnEl.innerHTML = `<i data-lucide="check" style="width:10px; height:10px; color:#34d399;"></i> <span>${uiText("✓ Copied", "✓ Скопировано")}</span>`;

                if (window.lucide) lucide.createIcons({ root: btnEl });

                setTimeout(() => {

                    btnEl.innerHTML = origHtml;

                    if (window.lucide) lucide.createIcons({ root: btnEl });

                }, 1800);

            }

            showToastNotification(successMsg || uiText("Copied to clipboard", "Скопировано в буфер обмена"));

        };



        if (navigator.clipboard && navigator.clipboard.writeText) {

            navigator.clipboard.writeText(textToCopy).then(notifyDone).catch(() => {

                if (fallbackCopy(textToCopy)) notifyDone();

            });

        } else {

            if (fallbackCopy(textToCopy)) notifyDone();

        }

    }



