    function updateDockRatingBar() {

        const bar = document.getElementById("dock-agent-rating-bar");

        if (!bar) return;

        const lastMsg = chatHistory[chatHistory.length - 1];

        const isRatingMsg = lastMsg && lastMsg.role === "assistant" && (

            (lastMsg.generation && lastMsg.generation.status === "completed") ||

            /(⭐|👍|👎|оценк|результат|устраивает|rating|satisf|rate|favorite)/i.test(lastMsg.text || "") ||

            !!lastMsg.asset_id

        );

        if (!isRatingMsg) {

            bar.style.display = "none";

            bar.innerHTML = "";

            return;

        }

        const targetType = lastMsg.asset_type || (lastMsg.generation?.mode === "video" || /video|ltx|видео/i.test(lastMsg.text || "") ? "video" : "image");

        let targetItem = null;

        if (lastMsg.asset_id) {

            targetItem = (targetType === "video" ? mediaVideos2D.find(v => v.id === lastMsg.asset_id) : mediaImages1D.find(i => i.id === lastMsg.asset_id))

                || mediaImages1D.find(i => i.id === lastMsg.asset_id) || mediaVideos2D.find(v => v.id === lastMsg.asset_id);

        }

        if (!targetItem && lastMsg.generation?.asset_id) {

            targetItem = (targetType === "video" ? mediaVideos2D.find(v => v.id === lastMsg.generation.asset_id) : mediaImages1D.find(i => i.id === lastMsg.generation.asset_id));

        }

        if (!targetItem && lastMsg.card_id) {

            targetItem = mediaImages1D.find(i => i.id === lastMsg.card_id);

        }

        if (!targetItem) {

            if (targetType === "video") targetItem = mediaVideos2D.find(v => v.id === activeVideoId) || mediaVideos2D[0];

            else targetItem = mediaImages1D.find(i => i.id === activeImageId) || mediaImages1D[0];

        }

        const curRating = (targetItem && targetItem.rating) || lastMsg.rating || null;

        bar.style.display = "flex";

        bar.innerHTML = `

            <div style="display: flex; align-items: center; gap: 4px; color: rgba(255,255,255,0.7); min-width: 0; overflow: hidden;">

                <span style="font-size: 9px; opacity: 0.8; white-space: nowrap;">${uiText("Rate generation:", "Оценка генерации:")}</span>

                ${curRating ? `<span style="font-size: 8.5px; padding: 0 4px; border-radius: 2px; font-weight: 600; font-family: 'JetBrains Mono', monospace; ${curRating === 'star' ? 'background: rgba(251,191,36,0.2); color: #fbbf24; border: 1px solid rgba(251,191,36,0.3);' : (curRating === 'up' ? 'background: rgba(34,197,94,0.2); color: #4ade80; border: 1px solid rgba(34,197,94,0.3);' : 'background: rgba(239,68,68,0.2); color: #f87171; border: 1px solid rgba(239,68,68,0.3);')}">${curRating === 'star' ? '⭐ ' + uiText("Fav", "Топ") : (curRating === 'up' ? '👍 ' + uiText("Good", "Лайк") : '👎 ' + uiText("Rework", "Доработка"))}</span>` : `<span style="font-size: 8.5px; color: rgba(255,255,255,0.35); font-style: italic;">${uiText("not rated", "нет оценки")}</span>`}

            </div>

            <div style="display: flex; gap: 3px; flex-shrink: 0;">

                <button class="vfx-btn dock-btn-rate" data-rate="star" ${tipAttr("Favorite (⭐)", "Избранное (⭐)")} style="padding: 1px 6px; font-size: 9.5px; border-radius: 3px; cursor: pointer; ${curRating === 'star' ? 'background: rgba(251,191,36,0.25); border: 1px solid #fbbf24; color: #fbbf24;' : 'background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.12); color: rgba(255,255,255,0.7);'}">⭐</button>

                <button class="vfx-btn dock-btn-rate" data-rate="up" ${tipAttr("Good (👍)", "Нравится (👍)")} style="padding: 1px 6px; font-size: 9.5px; border-radius: 3px; cursor: pointer; ${curRating === 'up' ? 'background: rgba(34,197,94,0.25); border: 1px solid #4ade80; color: #4ade80;' : 'background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.12); color: rgba(255,255,255,0.7);'}">👍</button>

                <button class="vfx-btn dock-btn-rate" data-rate="down" ${tipAttr("Needs rework (👎)", "На доработку (👎)")} style="padding: 1px 6px; font-size: 9.5px; border-radius: 3px; cursor: pointer; ${curRating === 'down' ? 'background: rgba(239,68,68,0.25); border: 1px solid #f87171; color: #f87171;' : 'background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.12); color: rgba(255,255,255,0.7);'}">👎</button>

            </div>

        `;

        bar.querySelectorAll(".dock-btn-rate").forEach(b => {

            b.onclick = (e) => {

                e.stopPropagation();

                const r = b.dataset.rate;

                if (targetItem) {

                    const newR = setAssetRating(targetItem, targetType, r);

                    lastMsg.rating = newR;

                    if (targetItem.id) {

                        lastMsg.asset_id = targetItem.id;

                        lastMsg.asset_type = targetType;

                    }

                    saveProjectChatHistory();

                    updateDockRatingBar();

                    if (activeTab === "agent") renderActiveCustomTab();

                } else {

                    showToastNotification(uiText("No media asset found to rate", "Ассет для оценки не найден"), true);

                }

            };

        });

    }

