                                const activeKey = keysArr.find(k => Number(k.frame) === Number(curF)) || keysArr.filter(k => Number(k.frame) <= Number(curF)).pop() || keysArr[0] || null;

                                const activeInterp = (activeKey && activeKey.interp) ? activeKey.interp : (getCurrentInterp ? getCurrentInterp() : "bezier");

                                const hOut = (activeKey && activeKey.handleOut) ? activeKey.handleOut : { dx: 0.333, dy: 0.333 };

                                const hIn = (activeKey && activeKey.handleIn) ? activeKey.handleIn : { dx: -0.333, dy: -0.333 };

