                    back.innerHTML = `<i data-lucide="arrow-left" style="width: 11px; height: 11px;"></i>${uiText("Back to", "Назад к")} «${esc(act.item.title || "")}»`;

                    back.onclick = () => { detailsBrowsing = false; renderActiveCustomTab(); };

