                actor_name: "Hero_Prop_3D",

                seed_stage1: 56,

                steps_stage1: 12,

                cfg_stage1: 7.5,

                seed_stage2: 42,

                steps_stage2: 20,

                cfg_stage2: 7.5,

                target_resolution: "1536",

                steps_upsample: 12,

                cfg_upsample: 7.5,

                texture_size: 2048,

                steps_texture: 12,

                cfg_texture: 1.0,

                flexicubes_res: 768,

                flexicubes_smooth: 20,

                decimation: 700000,

